#!/usr/bin/env python3
import os
import sys
from pathlib import Path

def lowercase_files(directory: str, dry_run: bool = True):
    path = Path(directory)
    renamed = 0
    for file in path.iterdir():
        if not file.is_file():
            continue
        new_name = file.parent / file.name.lower()
        if new_name == file:
            continue
        if dry_run:
            print(f'Would rename: {file.name} -> {new_name.name}')
        else:
            file.rename(new_name)
            print(f'Renamed: {file.name} -> {new_name.name}')
        renamed += 1
    action = 'Would rename' if dry_run else 'Renamed'
    print(f'\n{action} {renamed} files.')
    if dry_run:
        print("Run with --apply to execute.")

if __name__ == '__main__':
    directory = sys.argv[1] if len(sys.argv) > 1 else '.'
    apply = '--apply' in sys.argv
    lowercase_files(directory, dry_run=not apply)
